// Parse the API response
const response = pm.response.json();

// TEST 1: Validate HTTP status code
pm.test("TC01 - Status code is 200", () => {
    pm.response.to.have.status(200);
});

// TEST 2: Validate response content type
pm.test("TC01 - Response is JSON", () => {
    pm.response.to.be.json;
});

// TEST 3: Validate token existence
pm.test("TC01 - Authentication token exists", () => {
    pm.expect(response).to.have.property("token");
    pm.expect(response.token).to.be.a("string").and.not.empty;
});

// TEST 4: Save token for subsequent requests
if (response.token) {
    pm.collectionVariables.set("token", response.token);
}

// TEST 5: Validate token was saved
pm.test("TC01 - Token saved successfully", () => {
    pm.expect(pm.collectionVariables.get("token"))
        .to.eql(response.token);
});

